    text-transform: uppercase;
  }
  .byline {
    margin-top: 18px;
    font-size: 1.15rem;
    font-weight: 600;
  }
  .byline strong { font-weight: 800; }
  .meta {
    margin-top: 22px;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
  }
